import{_ as e,o as t,c as s,a2 as r}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"给自己的业务接入可观测性","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/observability","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/observability.md","filePath":"tutorials/observability.md"}'),i={name:"tutorials/observability.md"};function o(l,a,n,p,d,c){return t(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="给自己的业务接入可观测性" tabindex="-1">给自己的业务接入可观测性 <a class="header-anchor" href="#给自己的业务接入可观测性" aria-label="Permalink to &quot;给自己的业务接入可观测性&quot;">​</a></h1><p>目标：从自己的 HTTP 请求定位到 Job、存储操作与审计，排查故障而不让观测影响业务提交。前提是已有<a href="./first-request">公开 API</a>，后台业务沿用<a href="./document-exports">Jobs</a>，成功事实写入<a href="./audit-history">Audit</a>。</p><h2 id="启动可选观测组合" tabindex="-1">启动可选观测组合 <a class="header-anchor" href="#启动可选观测组合" aria-label="Permalink to &quot;启动可选观测组合&quot;">​</a></h2><p>仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-observability</span></span></code></pre></div><p>它启动正常开发服务与 Collector、Tempo、Loki、Prometheus、Grafana。打开 <a href="http://127.0.0.1:3300" target="_blank" rel="noreferrer">Grafana</a> 的 SaaS operations 看板；本地匿名只读、查询端口仅 loopback，不是生产登录方案。普通 <code>just dev</code> 不启动这些服务。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/compose.observability.yaml" target="_blank" rel="noreferrer">Compose overlay</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/deploy/observability/collector.yaml" target="_blank" rel="noreferrer">Collector 配置</a>固定实际服务与数据源；端口通过 TELEMETRY_HTTP_PORT/TEMPO_PORT/LOKI_PORT/PROMETHEUS_PORT/GRAFANA_PORT 配置。独立操作可用 <code>just observability-up / observability-validate / observability-down</code>；单独启动 Collector 不让已运行进程自动开启导出，应用须重启或明确配置 TELEMETRY_ENDPOINT/TELEMETRY_LOG_DIRECTORY。</p><h2 id="沿用公共接线" tabindex="-1">沿用公共接线 <a class="header-anchor" href="#沿用公共接线" aria-label="Permalink to &quot;沿用公共接线&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer">HTTP 上下文</a>生成真实 request_id/trace span，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Jobs 入队</a>持久化安全 parent/correlation/actor，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">Worker</a>为每次 attempt 建独立 span，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/object_storage.rs" target="_blank" rel="noreferrer">存储适配器</a>记录有限操作/结果。自己的模块无需让 Domain 依赖 OTel。</p><p>请求返回 <code>x-request-id / x-trace-id</code>，可在 Tempo 查询后关联 Loki。HTTP span 可在排队前结束，Worker 从数据库恢复 W3C parent；重启/重试创建新 span，不复用 span ID。traceparent 只作观测，不作授权，不持久化 baggage/tracestate/raw URI/完整 headers。</p><p>自己的 use case 只追加必要静态事件；方法与字段摘录：</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tracing</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(action </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tickets.export.requested&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;business request accepted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>在真实成功位置记录事件，授权成功后才记录 actor；不记录正文、token、密码、signed URL、原始 AWS/Redis 错误。沿用有限 route/kind/operation/outcome 标签，用户/Job/资源/trace ID 只作关联字段，不作 metric label。</p><h2 id="从关联查到持久结果" tabindex="-1">从关联查到持久结果 <a class="header-anchor" href="#从关联查到持久结果" aria-label="Permalink to &quot;从关联查到持久结果&quot;">​</a></h2><p>Loki 查询使用完整 trace ID 字符串替换示例值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{service_name=~&quot;saas-api|saas-worker&quot;} |= &quot;YOUR_TRACE_ID&quot;</span></span>
<span class="line"><span>sum by (route, status) (rate(saas_http_requests_total[5m]))</span></span>
<span class="line"><span>sum by (kind, outcome) (rate(saas_jobs_attempts_total[5m]))</span></span></code></pre></div><p>第一行是 LogQL，后两行是 PromQL。JSON 日志把上下文保存在 span/spans、事件放 fields，不假设全部顶层。rate 至少等待两次抓取；Histogram P95 为桶内近似值。attempt 的 transient 不等于整个 Job 最终失败，必须对照任务 batch/history、业务结果和 Audit；看到 span 不证明事务提交。</p><h2 id="故障不能反压业务" tabindex="-1">故障不能反压业务 <a class="header-anchor" href="#故障不能反压业务" aria-label="Permalink to &quot;故障不能反压业务&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/platform/src/telemetry/mod.rs" target="_blank" rel="noreferrer">Platform telemetry</a>默认 span 队列 512、batch 64、日志有损队列 1024，满时丢观测；OTLP 总预算 1 秒，不自动重试。Collector 有 memory limiter、有限队列和最多 10 秒重试。Collector 不可用不使数据库 ready 失败、不触发重新执行业务。</p><p>TELEMETRY_ENDPOINT 为空禁用 exporter，当前只支持本地 HTTP loopback/collector 服务名。无效 parent 创建新 trace；上游不采样时即使响应有 ID，后端可能没有导出 trace。输出只接本项目受控 saas_* target，TRACE 级也不开放第三方 secret 输出。</p><p>关停先 drain 业务，再有界关闭 provider；Trace 最多 2 秒，当前 metrics reader 最多 5 秒，日志也有限等待，允许丢数据。应用文件按小时轮转最多 24 个，不是精确磁盘配额；Prometheus/Loki retention 异步，开发卷需检查容量。生产自行定义日志预算/留存，不把开发 profile 当无限保存。</p><h2 id="验证接入" tabindex="-1">验证接入 <a class="header-anchor" href="#验证接入" aria-label="Permalink to &quot;验证接入&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry_outage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry_shutdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/telemetry.rs" target="_blank" rel="noreferrer">公开测试</a>捕获真实 OTLP protobuf 并驱动 HTTP/Worker/存储，检查 parent、actor、审计和有限标签；<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/telemetry_outage.rs" target="_blank" rel="noreferrer">故障</a>与<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/telemetry_shutdown.rs" target="_blank" rel="noreferrer">关停</a>检查阻塞出口仍完成业务、有限积压和退出。</p><p>自己的业务应提供对应的 HTTP/任务结果与观测查询场景。部署自己的 SaaS 继续<a href="./single-machine-production">生产指南</a>。</p><p>观测接线变更时可运行 <code>node scripts/knowledge-observability-smoke.mjs</code>，在独立环境查询真实 Tempo/Loki/Prometheus/Grafana 与 Audit，保存安全关联 ID。它是知识库参考业务 smoke；容量验证见<a href="./perf-gates">性能预算</a>。</p><hr><p>源码版本：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/tutorials/19-observability.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,28)])])}const u=e(i,[["render",o]]);export{b as __pageData,u as default};
